//! Arrow binding parity (ex-510).
//!
//! `tests/fixtures/binding.json` is upstream's own
//! `packages/element/src/binding.ts` (and the `utils.ts` helpers it calls)
//! at the pinned commit, generated by `tools/goldens/binding-fixtures.mjs`:
//! the binding gap and distance, `normalizeFixedPoint`, and on hand-written
//! and seeded random scenes of every bindable type and arrow kind the
//! read-only binding geometry (fixed points, `updateBoundPoint`, outline
//! snapping, corner avoidance, grid snapping, midpoints, the diagonal
//! projection, side midpoints, the binding strategies for dragged ends)
//! and the mutating calls (`updateBoundElements`, `bindBindingElement`,
//! `unbindBindingElement`, `bindOrUnbindBindingElement(s)`,
//! `updateBindings`, `reanchorBindingsToOutline`, the deletion and
//! duplication fixes), each compared element by element, number for
//! number.

use std::collections::{HashMap, HashSet};

use excali_core::element::{BindMode, Element, FixedPointBinding};
use excali_editor::binding::{
    avoid_rectangular_corner, bind_binding_element, bind_binding_element_to_fixed_point,
    bind_or_unbind_binding_element, bind_or_unbind_binding_elements,
    bind_point_to_snap_to_element_outline, calculate_fixed_point_for_elbow_arrow_binding,
    calculate_fixed_point_for_non_elbow_arrow_binding, fix_bindings_after_deletion,
    fix_duplicated_bindings_after_duplication, get_all_midpoints, get_arrow_local_fixed_points,
    get_binding_gap, get_binding_side_mid_point,
    get_binding_strategy_for_dragging_binding_element_endpoints, get_elbow_arrow_snap_mid_point,
    get_global_fixed_point_for_bindable_element, get_global_fixed_points,
    get_snap_outline_mid_point, is_fixed_point, max_binding_distance_simple, normalize_fixed_point,
    project_fixed_point_onto_diagonal, reanchor_bindings_to_outline, snap_bound_point_to_grid,
    unbind_binding_element, update_bindings, update_bound_elements, update_bound_point,
    BindingAppState, BindingEnd, BindingEnv, BindingOpts, BindingStrategy,
    LinearElementInitialState, BASE_ARROW_MIN_LENGTH, BASE_BINDING_GAP, FOCUS_POINT_SIZE,
};
use excali_editor::binding_highlight::{
    binding_highlight, BindingHighlight, HighlightAppState, HighlightOutline, SuggestedBinding,
};
use excali_editor::scene::{MutationEnv, Scene};
use excali_scene::shape::Theme;
use excali_text::text_measurements::{CharCountTextMetrics, CharWidthCache, TextMetricsProvider};
use serde_json::Value;

const FIXTURE: &str = include_str!("fixtures/binding.json");

fn fixture() -> Value {
    serde_json::from_str(FIXTURE).expect("binding.json parses")
}

// -- values ---------------------------------------------------------------------------

fn element(value: &Value) -> Element {
    Element::from_map(value.as_object().expect("an element").clone())
        .expect("an element upstream built")
}

fn elements(value: &Value) -> Vec<Element> {
    value
        .as_array()
        .expect("elements")
        .iter()
        .map(element)
        .collect()
}

fn num(v: &Value) -> f64 {
    match v {
        Value::String(s) => match s.as_str() {
            "NaN" => f64::NAN,
            "Infinity" => f64::INFINITY,
            "-Infinity" => f64::NEG_INFINITY,
            other => panic!("a number, got {other}"),
        },
        _ => v.as_f64().unwrap_or_else(|| panic!("a number, got {v}")),
    }
}

fn point(v: &Value) -> [f64; 2] {
    [num(&v[0]), num(&v[1])]
}

fn opt_point(v: &Value) -> Option<[f64; 2]> {
    if v.is_null() {
        None
    } else {
        Some(point(v))
    }
}

fn opt_num(v: &Value) -> Option<f64> {
    if v.is_null() {
        None
    } else {
        Some(num(v))
    }
}

fn string(v: &Value) -> &str {
    v.as_str().unwrap_or_else(|| panic!("a string, got {v}"))
}

fn ids(v: &Value) -> Vec<String> {
    v.as_array()
        .expect("ids")
        .iter()
        .map(|id| string(id).to_string())
        .collect()
}

fn opt_ids(v: &Value) -> Option<Vec<String>> {
    if v.is_null() {
        None
    } else {
        Some(ids(v))
    }
}

fn end(v: &Value) -> BindingEnd {
    match string(v) {
        "start" => BindingEnd::Start,
        "end" => BindingEnd::End,
        other => panic!("startOrEnd {other}"),
    }
}

fn mode(v: &Value) -> BindMode {
    match string(v) {
        "inside" => BindMode::Inside,
        "orbit" => BindMode::Orbit,
        "skip" => BindMode::Skip,
        other => panic!("mode {other}"),
    }
}

fn binding(v: &Value) -> FixedPointBinding {
    FixedPointBinding {
        element_id: string(&v["elementId"]).to_string(),
        fixed_point: point(&v["fixedPoint"]),
        mode: mode(&v["mode"]),
    }
}

fn app_state(v: &Value, complex: bool) -> BindingAppState {
    let linear = &v["selectedLinearElement"];
    BindingAppState {
        zoom: num(&v["zoom"]),
        is_binding_enabled: v["isBindingEnabled"] == true,
        is_midpoint_snapping_enabled: v["isMidpointSnappingEnabled"] == true,
        grid_mode_enabled: v["gridModeEnabled"] == true,
        grid_size: opt_num(&v["gridSize"]),
        bind_mode: mode(&v["bindMode"]),
        selected_linear_element: if linear.is_null() {
            None
        } else {
            Some(LinearElementInitialState {
                origin: opt_point(&linear["origin"]),
                arrow_start_is_inside: linear["arrowStartIsInside"] == true,
                alt_focus_point: opt_point(&linear["altFocusPoint"]),
                arrow_other_endpoint_initial_binding: if linear["arrowOtherEndpointInitialBinding"]
                    .is_null()
                {
                    None
                } else {
                    Some(mode(&linear["arrowOtherEndpointInitialBinding"]["mode"]))
                },
            })
        },
        complex_bindings: complex,
    }
}

fn opts(v: &Value) -> BindingOpts {
    BindingOpts {
        new_arrow: v["newArrow"] == true,
        angle_locked: v["angleLocked"] == true,
        alt_key: v["altKey"] == true,
        finalize: v["finalize"] == true,
        initial_binding: v["initialBinding"] == true,
        grid_size: opt_num(&v["gridSize"]),
        shift_key: v["shiftKey"] == true,
    }
}

fn dragging_points(v: &Value) -> Vec<(usize, [f64; 2])> {
    v.as_array()
        .expect("draggingPoints")
        .iter()
        .map(|e| (e[0].as_u64().expect("index") as usize, point(&e[1])))
        .collect()
}

// -- comparison ---------------------------------------------------------------------

/// Two numbers as the same double (`-0` equal to `0`): `excali_math::js`
/// computes `Math.sin`, `Math.cos` and `Math.atan2` as Node 26's V8 does
/// (ADR-011), so a rotated element's or an ellipse's numbers, and the
/// outline intersections binding reads (`intersectElementWithLineSegment`,
/// ex-507), are upstream's to the last bit.
fn same_number(a: f64, e: f64) -> bool {
    a == e
}

fn same_json(actual: &Value, expected: &Value, path: &str) -> Result<(), String> {
    match (actual, expected) {
        (Value::Number(a), Value::Number(e)) => {
            let (a, e) = (a.as_f64().expect("f64"), e.as_f64().expect("f64"));
            if same_number(a, e) {
                Ok(())
            } else {
                Err(format!("{path}: {a} != {e} (expected)"))
            }
        }
        (Value::Array(a), Value::Array(e)) => {
            if a.len() != e.len() {
                return Err(format!(
                    "{path}: {} items != {} (expected)",
                    a.len(),
                    e.len()
                ));
            }
            for (i, (a, e)) in a.iter().zip(e).enumerate() {
                same_json(a, e, &format!("{path}[{i}]"))?;
            }
            Ok(())
        }
        (Value::Object(a), Value::Object(e)) => {
            for key in e.keys().chain(a.keys()) {
                if key == "versionNonce" || key == "updated" {
                    continue;
                }
                match (a.get(key), e.get(key)) {
                    (Some(av), Some(ev)) => same_json(av, ev, &format!("{path}.{key}"))?,
                    (None, Some(ev)) => {
                        return Err(format!("{path}.{key}: missing, expected {ev}"))
                    }
                    (Some(av), None) => return Err(format!("{path}.{key}: {av}, expected no key")),
                    (None, None) => unreachable!(),
                }
            }
            Ok(())
        }
        (a, e) if a == e => Ok(()),
        (a, e) => Err(format!("{path}: {a} != {e} (expected)")),
    }
}

fn point_json(p: Option<[f64; 2]>) -> Value {
    match p {
        Some([x, y]) => serde_json::json!([x, y]),
        None => Value::Null,
    }
}

fn check(actual: &Value, expected: &Value, context: &str) {
    same_json(actual, expected, context)
        .unwrap_or_else(|e| panic!("{e}\n  port:     {actual}\n  upstream: {expected}"));
}

fn strategy_json(s: &BindingStrategy) -> Value {
    match s {
        BindingStrategy::Keep => {
            serde_json::json!({"mode": "keep", "element": null, "focusPoint": null})
        }
        BindingStrategy::Unbind => {
            serde_json::json!({"mode": null, "element": null, "focusPoint": null})
        }
        BindingStrategy::Bind {
            mode,
            element,
            focus_point,
        } => serde_json::json!({
            "mode": match mode {
                BindMode::Inside => "inside",
                BindMode::Orbit => "orbit",
                BindMode::Skip => "skip",
            },
            "element": element,
            "focusPoint": [focus_point[0], focus_point[1]],
        }),
    }
}

/// The element JSON without the keys upstream's random generator and
/// clock fill (`versionNonce`, `updated`).
fn stable(e: &Element) -> Value {
    let mut map = e.to_map();
    map.remove("versionNonce");
    map.remove("updated");
    Value::Object(map)
}

/// The scene after an op against upstream's: the elements upstream
/// changed as upstream left them, every other element as it was.
fn compare_changes(before: &[Element], scene: &Scene, changes: &Value, context: &str) {
    let expected: HashMap<&str, &Value> = changes
        .as_array()
        .expect("changes")
        .iter()
        .map(|c| (string(&c["id"]), c))
        .collect();
    assert_eq!(
        scene.elements().len(),
        before.len(),
        "{context}: element count"
    );
    for (actual, prior) in scene.elements().iter().zip(before) {
        let id = actual.base.id.as_str();
        let actual_json = Value::Object(actual.to_map());
        match expected.get(id) {
            Some(change) => check(&actual_json, change, &format!("{context} {id}")),
            None => assert_eq!(
                stable(actual),
                stable(prior),
                "{context}: {id} changed, upstream left it"
            ),
        }
    }
}

// -- the environment ------------------------------------------------------------------

#[derive(Default)]
struct Env {
    char_widths: CharWidthCache,
}

impl MutationEnv for Env {
    fn random_integer(&mut self) -> f64 {
        0.0
    }
    fn now(&mut self) -> f64 {
        1.0
    }
}

impl BindingEnv for Env {
    fn text(&mut self) -> (&dyn TextMetricsProvider, &mut CharWidthCache) {
        (&CharCountTextMetrics, &mut self.char_widths)
    }
}

// -- queries ---------------------------------------------------------------------------

fn run_query(scene: &Scene, q: &Value, context: &str) {
    let map = scene.elements_map();
    let get = |key: &str| -> &Element {
        let id = string(&q[key]);
        map.get(id)
            .unwrap_or_else(|| panic!("{context}: no element {id}"))
    };
    let expected = &q["result"];
    let actual: Value = match string(&q["fn"]) {
        "globalFixedPoint" => point_json(Some(get_global_fixed_point_for_bindable_element(
            point(&q["fixedPoint"]),
            get("element"),
        ))),
        "globalFixedPoints" => {
            let [s, e] = get_global_fixed_points(get("arrow"), &map);
            serde_json::json!([s, e])
        }
        "arrowLocalFixedPoints" => {
            let [s, e] = get_arrow_local_fixed_points(get("arrow"), &map);
            serde_json::json!([s, e])
        }
        "updateBoundPoint" => {
            let arrow = get("arrow");
            let linear = arrow.kind.linear().expect("an arrow");
            let which = end(&q["startOrEnd"]);
            let b = match which {
                BindingEnd::Start => linear.start_binding.as_ref(),
                BindingEnd::End => linear.end_binding.as_ref(),
            };
            point_json(update_bound_point(
                arrow,
                which,
                b,
                get("bindable"),
                &map,
                q["dragging"] == true,
            ))
        }
        "snapToOutline" => point_json(Some(bind_point_to_snap_to_element_outline(
            get("arrow"),
            get("bindable"),
            end(&q["startOrEnd"]),
            &map,
            num(&q["zoom"]),
            if q["intersector"].is_null() {
                None
            } else {
                Some([point(&q["intersector"][0]), point(&q["intersector"][1])])
            },
            q["midpointSnapping"] == true,
        ))),
        "avoidCorner" => point_json(Some(avoid_rectangular_corner(
            get("arrow"),
            get("target"),
            &map,
            point(&q["point"]),
        ))),
        "fixedPointElbow" => point_json(Some(calculate_fixed_point_for_elbow_arrow_binding(
            get("arrow"),
            get("target"),
            end(&q["startOrEnd"]),
            &map,
            num(&q["zoom"]),
            q["snapToOutline"] == true,
            q["midpointSnapping"] == true,
        ))),
        "fixedPointSimple" => point_json(Some(calculate_fixed_point_for_non_elbow_arrow_binding(
            get("arrow"),
            get("target"),
            end(&q["startOrEnd"]),
            &map,
            opt_point(&q["focusPoint"]),
        ))),
        "snapToGrid" => point_json(Some(snap_bound_point_to_grid(
            point(&q["outlinePoint"]),
            get("bindable"),
            &map,
            opt_num(&q["gridSize"]),
            get("arrow"),
            opt_point(&q["adjacentPoint"]),
        ))),
        "allMidpoints" => Value::Array(
            get_all_midpoints(get("element"), &map)
                .into_iter()
                .map(|p| point_json(Some(p)))
                .collect(),
        ),
        "elbowSnapMidPoint" => match get_elbow_arrow_snap_mid_point(
            point(&q["point"]),
            get("element"),
            &map,
            num(&q["zoom"]),
        ) {
            Some(s) => serde_json::json!({"point": [s.point[0], s.point[1]], "onAxis": s.on_axis}),
            None => Value::Null,
        },
        "snapOutlineMidPoint" => point_json(get_snap_outline_mid_point(
            point(&q["point"]),
            get("element"),
            &map,
            num(&q["zoom"]),
            q["elbowed"] == true,
        )),
        "projectOntoDiagonal" => point_json(project_fixed_point_onto_diagonal(
            get("arrow"),
            point(&q["point"]),
            get("element"),
            end(&q["startOrEnd"]),
            &map,
            num(&q["zoom"]),
            q["midpointSnapping"] == true,
        )),
        "sideMidPoint" => point_json(get_binding_side_mid_point(&binding(&q["binding"]), &map)),
        "strategy" => {
            let complex = q["complex"] == true;
            let elements: Vec<&Element> = scene.non_deleted();
            match get_binding_strategy_for_dragging_binding_element_endpoints(
                get("arrow"),
                &dragging_points(&q["draggingPoints"]),
                point(&q["pointer"]),
                &map,
                &elements,
                &app_state(&q["appState"], complex),
                &opts(&q["opts"]),
            ) {
                Ok((start, end)) => {
                    serde_json::json!({"start": strategy_json(&start), "end": strategy_json(&end)})
                }
                Err(error) => serde_json::json!({"error": error.to_string()}),
            }
        }
        other => panic!("{context}: query {other}"),
    };
    check(&actual, expected, context);
}

// -- ops -------------------------------------------------------------------------------

/// A history step's binding, assigned as the delta assigns it: the arrow's
/// binding at that end and the arrow in the target's `boundElements`
/// (no version bump, as the generator assigns it).
fn assign_binding(scene: &mut Scene, b: &Value) {
    let mut arrow = scene.get(string(&b["arrow"])).cloned().expect("the arrow");
    let target_id = string(&b["elementId"]);
    let binding = FixedPointBinding {
        element_id: target_id.to_string(),
        fixed_point: point(&b["fixedPoint"]),
        mode: BindMode::Orbit,
    };
    let linear = arrow.kind.linear_mut().expect("an arrow");
    match end(&b["startOrEnd"]) {
        BindingEnd::Start => linear.start_binding = Some(binding),
        BindingEnd::End => linear.end_binding = Some(binding),
    }
    let mut target = scene.get(target_id).cloned().expect("the target");
    let bound = target.base.bound_elements.get_or_insert_with(Vec::new);
    if !bound.iter().any(|e| e.id == arrow.base.id) {
        bound.push(excali_core::element::BoundElement {
            id: arrow.base.id.clone(),
            kind: excali_core::element::BoundElementType::Arrow,
        });
    }
    scene.replace_element(arrow);
    scene.replace_element(target);
}

fn run_op(case_elements: &[Element], op: &Value, context: &str) {
    let kind = string(&op["op"]);
    if kind == "fixAfterDuplication" {
        let mut duplicates = elements(&op["duplicates"]);
        let id_map: HashMap<String, String> = op["idMap"]
            .as_object()
            .expect("idMap")
            .iter()
            .map(|(k, v)| (k.clone(), string(v).to_string()))
            .collect();
        fix_duplicated_bindings_after_duplication(&mut duplicates, &id_map)
            .unwrap_or_else(|e| panic!("{context}: {e}"));
        let actual = Value::Array(
            duplicates
                .iter()
                .map(|e| Value::Object(e.to_map()))
                .collect(),
        );
        check(&actual, &op["result"], context);
        return;
    }
    let before = if op["elements"].is_null() {
        case_elements.to_vec()
    } else {
        elements(&op["elements"])
    };
    let mut scene = Scene::new(before.clone());
    let mut env = Env::default();
    match kind {
        "updateBoundElements" => {
            let changed_elements = opt_ids(&op["changedElements"]);
            update_bound_elements(
                &mut scene,
                &mut env,
                string(&op["changed"]),
                opt_ids(&op["simultaneouslyUpdated"]).as_deref(),
                changed_elements.as_deref(),
            );
        }
        "redrawBoundArrows" => {
            for step in op["steps"].as_array().expect("steps") {
                for b in step["bindings"].as_array().expect("bindings") {
                    assign_binding(&mut scene, b);
                }
                let changed = ids(&step["changed"]);
                for id in ids(&step["redraw"]) {
                    update_bound_elements(&mut scene, &mut env, &id, None, Some(&changed));
                }
            }
        }
        "bind" => bind_binding_element(
            &mut scene,
            &mut env,
            string(&op["arrow"]),
            string(&op["target"]),
            mode(&op["mode"]),
            end(&op["startOrEnd"]),
            num(&op["zoom"]),
            opt_point(&op["focusPoint"]),
            op["snapToOutline"] == true,
            op["midpointSnapping"] == true,
        ),
        "bindToFixedPoint" => bind_binding_element_to_fixed_point(
            &mut scene,
            &mut env,
            string(&op["arrow"]),
            string(&op["target"]),
            end(&op["startOrEnd"]),
            point(&op["fixedPoint"]),
        ),
        "unbind" => {
            let result = unbind_binding_element(
                &mut scene,
                &mut env,
                string(&op["arrow"]),
                end(&op["startOrEnd"]),
            );
            assert_eq!(
                result.as_deref(),
                op["result"].as_str(),
                "{context}: unbindBindingElement result"
            );
        }
        "bindOrUnbind" => {
            let complex = op["complex"] == true;
            let result = bind_or_unbind_binding_element(
                &mut scene,
                &mut env,
                string(&op["arrow"]),
                &dragging_points(&op["draggingPoints"]),
                point(&op["pointer"]),
                &app_state(&op["appState"], complex),
                &opts(&op["opts"]),
            );
            let actual = match result {
                Ok((start, end)) => {
                    serde_json::json!({"start": strategy_json(&start), "end": strategy_json(&end)})
                }
                Err(error) => serde_json::json!({"error": error.to_string()}),
            };
            check(&actual, &op["result"], &format!("{context} result"));
        }
        "bindOrUnbindAll" => bind_or_unbind_binding_elements(
            &mut scene,
            &mut env,
            &ids(&op["arrows"]),
            &app_state(&op["appState"], false),
        ),
        "updateBindings" => {
            let result = update_bindings(
                &mut scene,
                &mut env,
                string(&op["element"]),
                &app_state(&op["appState"], false),
                opt_ids(&op["simultaneouslyUpdated"]).as_deref(),
            );
            assert_eq!(
                result.err().map(|e| e.to_string()).as_deref(),
                op["error"].as_str(),
                "{context}: updateBindings error"
            );
        }
        "reanchor" => reanchor_bindings_to_outline(
            &mut scene,
            &mut env,
            string(&op["element"]),
            num(&op["zoom"]),
        ),
        "fixAfterDeletion" => {
            fix_bindings_after_deletion(&mut scene, &mut env, &ids(&op["deleted"]))
        }
        other => panic!("{context}: op {other}"),
    }
    compare_changes(&before, &scene, &op["changes"], context);
}

// -- tests -----------------------------------------------------------------------------

#[test]
fn constants_match_upstream() {
    let c = &fixture()["constants"];
    assert_eq!(BASE_BINDING_GAP, num(&c["BASE_BINDING_GAP"]));
    assert_eq!(BASE_ARROW_MIN_LENGTH, num(&c["BASE_ARROW_MIN_LENGTH"]));
    assert_eq!(FOCUS_POINT_SIZE, num(&c["FOCUS_POINT_SIZE"]));
    for g in c["gaps"].as_array().expect("gaps") {
        let mut rect = element(&serde_json::json!({
            "id": "r", "type": "rectangle", "x": 0, "y": 0, "width": 10, "height": 10,
            "angle": 0, "strokeColor": "#1e1e1e", "backgroundColor": "transparent",
            "fillStyle": "solid", "strokeWidth": 2, "strokeStyle": "solid", "roughness": 1,
            "opacity": 100, "groupIds": [], "frameId": null, "index": null, "roundness": null,
            "seed": 1, "version": 1, "versionNonce": 0, "isDeleted": false,
            "boundElements": null, "updated": 1, "link": null, "locked": false
        }));
        rect.base.stroke_width = num(&g["strokeWidth"]);
        assert_eq!(get_binding_gap(&rect), num(&g["gap"]), "gap for {g}");
    }
    for d in c["distances"].as_array().expect("distances") {
        // an absent zoom is zoom 1
        let zoom = opt_num(&d["zoom"]).unwrap_or(1.0);
        assert_eq!(
            max_binding_distance_simple(zoom),
            num(&d["distance"]),
            "distance at zoom {zoom}"
        );
    }
}

#[test]
fn normalize_fixed_point_matches_upstream() {
    for item in fixture()["normalizeFixedPoint"].as_array().expect("items") {
        let input = point(&item["input"]);
        assert_eq!(
            is_fixed_point(&input),
            item["isFixedPoint"] == true,
            "isFixedPoint({input:?})"
        );
        assert_eq!(
            normalize_fixed_point(input),
            point(&item["result"]),
            "normalizeFixedPoint({input:?})"
        );
    }
}

#[test]
fn fixture_covers_every_call_and_outcome() {
    let f = fixture();
    let mut fns = HashSet::new();
    let mut ops = HashSet::new();
    let mut outcomes = HashSet::new();
    for c in f["cases"].as_array().expect("cases") {
        for q in c["queries"].as_array().expect("queries") {
            fns.insert(string(&q["fn"]).to_string());
            if q["fn"] == "strategy" && q["result"]["start"].is_object() {
                for side in ["start", "end"] {
                    outcomes.insert(q["result"][side]["mode"].to_string());
                }
            }
            if q["fn"] == "strategy" && q["result"]["error"].is_string() {
                outcomes.insert("error".to_string());
            }
        }
        for o in c["ops"].as_array().expect("ops") {
            let with_changes = o["changes"].as_array().is_some_and(|c| !c.is_empty());
            ops.insert(format!(
                "{}{}",
                string(&o["op"]),
                if with_changes { "+" } else { "" }
            ));
        }
    }
    for f in [
        "globalFixedPoint",
        "globalFixedPoints",
        "arrowLocalFixedPoints",
        "updateBoundPoint",
        "snapToOutline",
        "avoidCorner",
        "fixedPointElbow",
        "fixedPointSimple",
        "snapToGrid",
        "allMidpoints",
        "elbowSnapMidPoint",
        "snapOutlineMidPoint",
        "projectOntoDiagonal",
        "sideMidPoint",
        "strategy",
    ] {
        assert!(fns.contains(f), "no {f} query");
    }
    for o in [
        "updateBoundElements+",
        "updateBoundElements",
        "redrawBoundArrows+",
        "bind+",
        "bindToFixedPoint+",
        "unbind+",
        "bindOrUnbind+",
        "bindOrUnbindAll",
        "updateBindings+",
        "reanchor+",
        "fixAfterDeletion+",
        "fixAfterDuplication",
    ] {
        assert!(ops.contains(o), "no {o} op");
    }
    for m in ["\"keep\"", "null", "\"inside\"", "\"orbit\""] {
        assert!(outcomes.contains(m), "no strategy answering {m}");
    }
}

