// -- the binding highlight -------------------------------------------------------------

/// Canvas calls as the generator's recording context writes them:
/// `[name, ...arguments]`, an assignment as a call of the property's name.
#[derive(Default)]
struct Calls(Vec<Value>);

impl Calls {
    fn call(&mut self, name: &str, args: &[f64]) {
        let mut c = vec![Value::from(name)];
        c.extend(args.iter().map(|&x| serde_json::json!(x)));
        self.0.push(Value::Array(c));
    }

    fn set(&mut self, name: &str, value: &str) {
        self.0.push(serde_json::json!([name, value]));
    }

    /// `translate(center)`, `rotate(angle)`, `translate(-center)`,
    /// `translate(x, y)`.
    fn place(&mut self, center: [f64; 2], angle: f64, x: f64, y: f64) {
        self.call("translate", &[center[0], center[1]]);
        self.call("rotate", &[angle]);
        self.call("translate", &[-center[0], -center[1]]);
        self.call("translate", &[x, y]);
    }

    fn disc(&mut self, p: [f64; 2], radius: f64) {
        self.call("beginPath", &[]);
        self.call(
            "arc",
            &[p[0], p[1], radius, 0.0, 2.0 * std::f64::consts::PI],
        );
        self.call("fill", &[]);
    }
}

/// The canvas calls that draw `h`, as the module docs of
/// `excali_editor::binding_highlight` describe them (the calls
/// `renderBindingHighlightForBindableElement_simple` makes).
fn highlight_calls(h: &BindingHighlight) -> Vec<Value> {
    let mut c = Calls::default();
    if let Some(clip) = h.frame_clip {
        c.call("translate", &[clip.x, clip.y]);
        c.call("beginPath", &[]);
        c.call(
            "roundRect",
            &[-1.0, -1.0, clip.width + 1.0, clip.height + 1.0, clip.radius],
        );
        c.call("clip", &[]);
        c.call("translate", &[-clip.x, -clip.y]);
    }
    c.call("save", &[]);
    match &h.outline {
        HighlightOutline::Frame {
            x,
            y,
            width,
            height,
            radius,
        } => {
            c.call("translate", &[*x, *y]);
            c.call("lineWidth", &[h.line_width]);
            c.set("strokeStyle", &h.color);
            c.call("beginPath", &[]);
            c.call("roundRect", &[0.0, 0.0, *width, *height, *radius]);
            c.call("stroke", &[]);
            c.call("closePath", &[]);
        }
        HighlightOutline::Ellipse {
            center,
            angle,
            x,
            y,
            width,
            height,
        } => {
            c.place(*center, *angle, *x, *y);
            c.call("lineWidth", &[h.line_width]);
            c.set("strokeStyle", &h.color);
            c.call("beginPath", &[]);
            c.call(
                "ellipse",
                &[
                    width / 2.0,
                    height / 2.0,
                    width / 2.0,
                    height / 2.0,
                    0.0,
                    0.0,
                    2.0 * std::f64::consts::PI,
                ],
            );
            c.call("closePath", &[]);
            c.call("stroke", &[]);
        }
        HighlightOutline::Outline {
            center,
            angle,
            x,
            y,
            sides,
            corners,
        } => {
            c.place(*center, *angle, *x, *y);
            c.call("lineWidth", &[h.line_width]);
            c.set("strokeStyle", &h.color);
            for [a, b] in sides {
                c.call("beginPath", &[]);
                c.call("moveTo", &[a[0] - x, a[1] - y]);
                c.call("lineTo", &[b[0] - x, b[1] - y]);
                c.call("stroke", &[]);
            }
            for [a, c1, c2, b] in corners {
                c.call("beginPath", &[]);
                c.call("moveTo", &[a[0] - x, a[1] - y]);
                c.call(
                    "bezierCurveTo",
                    &[
                        c1[0] - x,
                        c1[1] - y,
                        c2[0] - x,
                        c2[1] - y,
                        b[0] - x,
                        b[1] - y,
                    ],
                );
                c.call("stroke", &[]);
            }
        }
    }
    c.call("restore", &[]);
    if h.draws_midpoints {
        c.call("save", &[]);
        c.set("fillStyle", h.midpoint_color);
        for &m in &h.midpoints {
            c.disc(m, h.midpoint_radius);
        }
        if let Some(m) = h.highlighted_midpoint {
            c.set("fillStyle", &h.color);
            c.disc(m, h.midpoint_radius);
        }
        c.call("restore", &[]);
    }
    c.0
}

#[test]
fn binding_highlight_matches_upstream() {
    let f = fixture();
    let mut count = 0;
    let (mut frames, mut ellipses, mut outlines, mut clipped, mut dots) = (0, 0, 0, 0, 0);
    for c in f["cases"].as_array().expect("cases") {
        let id = string(&c["id"]);
        let scene = Scene::new(elements(&c["elements"]));
        let map = scene.elements_map();
        for (n, h) in c["highlights"]
            .as_array()
            .expect("highlights")
            .iter()
            .enumerate()
        {
            let context = format!("{id} highlight {n} ({})", string(&h["element"]));
            let highlight = binding_highlight(
                &SuggestedBinding {
                    element_id: string(&h["element"]).to_string(),
                    mid_point: opt_point(&h["midPoint"]),
                },
                &map,
                &HighlightAppState {
                    zoom: num(&h["zoom"]),
                    theme: if h["theme"] == "dark" {
                        Theme::Dark
                    } else {
                        Theme::Light
                    },
                    is_midpoint_snapping_enabled: h["midpointSnapping"] == true,
                    grid_mode_enabled: h["gridMode"] == true,
                    elbow: h["elbow"] == true,
                },
                opt_point(&h["pointer"]),
                h["angleLocked"] == true,
            )
            .unwrap_or_else(|| panic!("{context}: no highlight"));
            match highlight.outline {
                HighlightOutline::Frame { .. } => frames += 1,
                HighlightOutline::Ellipse { .. } => ellipses += 1,
                HighlightOutline::Outline { .. } => outlines += 1,
            }
            clipped += usize::from(highlight.frame_clip.is_some());
            dots += highlight.midpoints.len();
            check(
                &Value::Array(highlight_calls(&highlight)),
                &h["calls"],
                &context,
            );
            count += 1;
        }
    }
    assert!(count > 400, "{count} highlights");
    for (what, n) in [
        ("frames", frames),
        ("ellipses", ellipses),
        ("outlines", outlines),
        ("clipped", clipped),
        ("midpoints", dots),
    ] {
        assert!(n > 0, "no highlight with {what}");
    }
}
